                            end
                        end
                    end)
                end
            end
            -- Scan CoreGui (tempat FyyUI render)
            pcall(function() renameGui(game:GetService("CoreGui")) end)
            -- Scan PlayerGui juga
            pcall(function()
                local lp = game:GetService("Players").LocalPlayer
                if lp then renameGui(lp:WaitForChild("PlayerGui", 3)) end
            end)
            warn("[SagaHub] UI renamed: FyyCommunity -> SagaHub")
        end)
    end)
    task.delay(6, function()
        pcall(function()
            local _mon_src = game:HttpGet(
                "https://cdn.jsdelivr.net/gh/Galangpratama-rox/Decode-SAE@main/SagaHub_Monitor.lua?v="..tostring(os.time()),
                true
            )
            if _mon_src and #_mon_src > 100 then
                loadstring(_mon_src)()
            end
        end)
    end)
    local StarterGui = game:GetService("StarterGui")
    pcall(function() StarterGui:SetCore("SendNotification", {Title="FyyCommunity ✅", Text="Executor: "..executor, Duration=5}) end)
    return _ret
else
    local StarterGui = game:GetService("StarterGui")
    pcall(function() StarterGui:SetCore("SendNotification", {Title="FyyCommunity ❌", Text="Payload failed — lihat console", Duration=6}) end)
    error("[FyyCommunity OneFile] Payload EXEC FAILED: " .. tostring(_ret))
end